from typing import Annotated
from fastmcp import FastMCP
from fastmcp.server.auth.providers.jwt import JWTVerifier
from mcp.types import ToolAnnotations

auth = JWTVerifier(                                   # tokens must be issued for THIS server
    jwks_uri="https://login.example-rta.in/.well-known/jwks.json",
    issuer="https://login.example-rta.in",
    audience="https://mcp.example-rta.in/mcp",
)
mcp = FastMCP("folio-lookup", auth=auth)

@mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, idempotentHint=True, openWorldHint=False))
def get_folio_summary(folio: Annotated[str, "Folio number, e.g. 12345678/90"]) -> dict:
    """Return schemes, units held and the latest NAV for one mutual-fund folio.
    Use it when an investor or distributor asks what a folio holds. Read-only."""
    return registry.summary(folio)

@mcp.resource("folio://schemes/{scheme_code}")
def scheme_factsheet(scheme_code: str) -> str:
    """Plain-text factsheet for one scheme: objective, benchmark, expense ratio."""
    return factsheets[scheme_code]

@mcp.prompt
def explain_statement(folio: str) -> str:
    return f"Explain the latest account statement for folio {folio} in plain language."

if __name__ == "__main__":
    mcp.run(transport="http", host="0.0.0.0", port=8000)   # use "stdio" for a local server
